       (!Number.isInteger(overflowCostCents) || overflowCostCents < 0)
     ) {
       throw new RangeError("overflowCostCents must be a non-negative integer");
     }
     this.sortedBrackets = [...brackets].sort((a, b) => a.upToGrams - b.upToGrams);
