        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(3000), new FixedAmountDiscountPolicy(3000)],
        "sum",
      );
      // Each returns min(3000, 5000) = 3000 → sum = 6000 (exceeds 5000; Cart clamps)
      expect(composite.computeDiscountCents(5000)).toBe(6000);
    });

    it("ignores NoDiscountPolicy contributions", () => {
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new PercentageDiscountPolicy(20)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // first: 10% of 10000 = 1000, remaining 9000
      // second: 10% of 9000 = 900, remaining 8100
      // total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(1000)],
        "chain",
      );
      // A: fixed 1000 from 5000 → remaining 4000, then 50% of 4000 = 2000 → total 3000
      // B: 50% of 5000 = 2500 → remaining 2500, then fixed min(1000, 2500)=1000 → total 3500
      expect(policyA.computeDiscountCents(5000)).toBe(3000);
      expect(policyB.computeDiscountCents(5000)).toBe(3500);
    });

    it("cannot exceed the subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(100), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 100% of 2000 = 2000, remaining 0
      // fixed on remaining 0 → 0
      // total = 2000 (the subtotal)
      expect(composite.computeDiscountCents(2000)).toBe(2000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});
