    // subtotal = 1100*2 + 2200*1 = 4400
    // discount = 10% of 4400 = 440
    // discounted = 3960
    // tax = 8.75% of 3960 = 346.5 → 346
    // shipping = 499
    // total = 3960 + 346 + 499 = 4805
    expect(result.totals.subtotalCents).toBe(4400);
    expect(result.totals.discountCents).toBe(440);
    expect(result.totals.taxCents).toBe(346);
    expect(result.totals.shippingCents).toBe(499);
    expect(result.totals.totalCents).toBe(4805);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });
});
